package envs

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"time"

	"mymac/internal/config"
	"mymac/internal/errs"
)

// Marker delimiters for the block mymac owns inside the shell rc files.
const (
	MarkerStart = "# >>> mymac env >>>"
	MarkerEnd   = "# <<< mymac env <<<"
)

// The block content mymac wants inside the rc file. It only sources the
// generated file; the real values live in env.sh.
const markerBody = `[ -f "$HOME/.config/mymac/env.sh" ] && . "$HOME/.config/mymac/env.sh"`

// EscapeSingleQuoted wraps a value in single quotes, escaping any single
// quote it contains. Inside single quotes a shell treats every character
// literally, so spaces, $, backticks, backslashes and newlines all survive
// untouched.
func EscapeSingleQuoted(value string) string {
	return "'" + strings.ReplaceAll(value, "'", `'\''`) + "'"
}

// RenderEnvSh builds the content of env.sh for the given variables.
//
// Only enabled variables are exported. PATH is handled by the caller because
// it needs the merged base value.
func RenderEnvSh(vars []Var) []byte {
	var b strings.Builder
	b.WriteString("# Generated by mymac. Do not edit by hand; changes will be overwritten.\n")
	b.WriteString("# source this file:  . ~/.config/mymac/env.sh\n")
	for _, v := range vars {
		if !v.Enabled || v.Name == "PATH" {
			continue
		}
		b.WriteString("export " + v.Name + "=" + EscapeSingleQuoted(v.Value) + "\n")
	}
	return []byte(b.String())
}

// RenderEnvShWithPath is RenderEnvSh plus the PATH fragments.
//
// PATH is never overwritten wholesale: the fragments are prepended and
// appended to whatever PATH the shell already has, using the dynamic form
//
//	export PATH='/opt/homebrew/bin':"$PATH"
//	export PATH="$PATH":'/custom/bin'
//
// so a PATH that changes later is still respected.
func RenderEnvShWithPath(vars []Var, cfg PathConfig) []byte {
	b := RenderEnvSh(vars)
	s := string(b)
	lines := strings.SplitAfter(s, "\n")
	var out strings.Builder
	for i, ln := range lines {
		out.WriteString(ln)
		if i == 1 {
			out.WriteString(pathExports(cfg))
		}
	}
	return []byte(out.String())
}

// pathExports renders the PATH fragment exports.
func pathExports(cfg PathConfig) string {
	if !cfg.Enabled {
		return ""
	}
	var b strings.Builder
	b.WriteString("# PATH fragments managed by mymac\n")
	for _, p := range cfg.Prepend {
		if p == "" {
			continue
		}
		b.WriteString("export PATH=" + EscapeSingleQuoted(p) + ":\"$PATH\"\n")
	}
	for _, p := range cfg.Append {
		if p == "" {
			continue
		}
		b.WriteString("export PATH=\"$PATH\":" + EscapeSingleQuoted(p) + "\n")
	}
	return b.String()
}

// MarkerBlock is the exact text mymac wants between the markers.
func MarkerBlock() string {
	return MarkerStart + "\n" + markerBody + "\n" + MarkerEnd + "\n"
}

// MarkerState describes the health of a managed marker block.
type MarkerState string

// Marker states.
const (
	MarkerOK       MarkerState = "ok"       // present and matching
	MarkerMissing  MarkerState = "missing"  // not there at all
	MarkerDamaged  MarkerState = "damaged"  // present but broken or edited
	MarkerConflict MarkerState = "conflict" // more than one block
)

// MarkerReport describes a file's marker block.
type MarkerReport struct {
	File   string      `json:"file"`
	State  MarkerState `json:"state"`
	Detail string      `json:"detail,omitempty"`
	Line   int         `json:"line,omitempty"`
}

// FindMarker locates the managed block in content.
//
// It returns the inner content, the state and the line number of the start
// marker. A file with a start marker but no end marker is "damaged": mymac
// will not touch it automatically because it cannot tell where the user's
// own content resumes.
func FindMarker(content string) (inner string, state MarkerState, line int, detail string) {
	starts := allIndexes(content, MarkerStart)
	ends := allIndexes(content, MarkerEnd)

	switch {
	case len(starts) == 0 && len(ends) == 0:
		return "", MarkerMissing, 0, "文件中没有 mymac 标记块"
	case len(starts) > 1 || len(ends) > 1:
		return "", MarkerConflict, lineOf(content, starts[0]),
			fmt.Sprintf("发现 %d 个起始标记和 %d 个结束标记", len(starts), len(ends))
	case len(starts) == 1 && len(ends) == 0:
		return "", MarkerDamaged, lineOf(content, starts[0]), "有起始标记但没有结束标记，块可能已被手动破坏"
	case len(starts) == 0 && len(ends) == 1:
		return "", MarkerDamaged, lineOf(content, ends[0]), "有结束标记但没有起始标记"
	}

	s := starts[0]
	e := ends[0]
	if e < s {
		return "", MarkerDamaged, lineOf(content, s), "结束标记出现在起始标记之前"
	}
	inner = content[s+len(MarkerStart) : e]
	inner = strings.TrimPrefix(inner, "\n")
	inner = strings.TrimSuffix(inner, "\n")
	return inner, MarkerOK, lineOf(content, s), ""
}

func allIndexes(s, sub string) []int {
	var out []int
	off := 0
	for {
		i := strings.Index(s[off:], sub)
		if i < 0 {
			return out
		}
		out = append(out, off+i)
		off += i + len(sub)
	}
}

func lineOf(s string, idx int) int {
	if idx < 0 || idx > len(s) {
		return 0
	}
	return strings.Count(s[:idx], "\n") + 1
}

// ReplaceMarker returns content with the managed block replaced.
//
// When the block is missing the block is appended at the end of the file,
// separated by a blank line. When the block is damaged or conflicting the
// content is returned unchanged and ok is false, so the caller can warn
// instead of clobbering the user's file.
func ReplaceMarker(content, block string) (out string, ok bool, reason string) {
	inner, state, _, detail := FindMarker(content)
	switch state {
	case MarkerMissing:
		if content != "" && !strings.HasSuffix(content, "\n") {
			content += "\n"
		}
		if content != "" {
			content += "\n"
		}
		return content + block, true, ""
	case MarkerDamaged, MarkerConflict:
		return content, false, detail
	}
	_ = inner

	s := strings.Index(content, MarkerStart)
	e := strings.Index(content, MarkerEnd)
	prefix := content[:s]
	suffix := content[e+len(MarkerEnd):]
	// Preserve whatever followed the end marker, minus the newline that
	// separated it from the block.
	if strings.HasPrefix(suffix, "\n") {
		suffix = suffix[1:]
	}
	_ = inner
	return prefix + block + suffix, true, ""
}

// UpsertShellFile makes sure the rc file sources env.sh.
//
// The file is backed up first, then rewritten atomically.
func UpsertShellFile(path string, block string) (MarkerReport, error) {
	rep := MarkerReport{File: path}

	data, err := os.ReadFile(path)
	if err != nil && !os.IsNotExist(err) {
		return rep, errs.Wrap(err, errs.KindPermission, "无法读取 %s", path)
	}
	content := string(data)

	inner, state, line, detail := FindMarker(content)
	switch state {
	case MarkerOK:
		if strings.TrimSpace(inner) == strings.TrimSpace(strings.TrimSuffix(block, "\n")) {
			rep.State = MarkerOK
			rep.Line = line
			return rep, nil
		}
	case MarkerDamaged, MarkerConflict:
		rep.State = state
		rep.Detail = detail
		rep.Line = line
		return rep, errs.New(errs.KindInvalid, "%s 的标记块已损坏，未做修改：%s", path, detail)
	}

	if err := BackupFile(path); err != nil {
		return rep, err
	}

	newContent, ok, reason := ReplaceMarker(content, block)
	if !ok {
		rep.State = MarkerDamaged
		rep.Detail = reason
		return rep, errs.New(errs.KindInvalid, "%s 的标记块已损坏，未做修改：%s", path, reason)
	}
	if err := WriteFileAtomic(path, []byte(newContent), 0o644); err != nil {
		return rep, err
	}
	rep.State = MarkerOK
	rep.Line = line
	return rep, nil
}

// RemoveShellBlock strips the managed block from a file, restoring the file
// to its pre-mymac content as far as the block is concerned.
func RemoveShellBlock(path string) error {
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return errs.Wrap(err, errs.KindPermission, "无法读取 %s", path)
	}
	content := string(data)
	_, state, _, detail := FindMarker(content)
	if state == MarkerMissing {
		return nil
	}
	if state != MarkerOK {
		return errs.New(errs.KindInvalid, "%s 的标记块已损坏，未做修改：%s", path, detail)
	}
	s := strings.Index(content, MarkerStart)
	e := strings.Index(content, MarkerEnd)
	prefix := content[:s]
	suffix := content[e+len(MarkerEnd):]
	suffix = strings.TrimPrefix(suffix, "\n")
	if err := BackupFile(path); err != nil {
		return err
	}
	return WriteFileAtomic(path, []byte(prefix+suffix), 0o644)
}

// BackupFile copies path into the config backup directory.
//
// Missing files are recorded as an empty backup so the restore flow still
// knows the file did not exist before.
func BackupFile(path string) error {
	dir := config.BackupDir()
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return errs.Wrap(err, errs.KindPermission, "无法创建备份目录")
	}
	name := fmt.Sprintf("%s-%s.bak", filepath.Base(path), time.Now().Format("20060102-150405"))
	dst := filepath.Join(dir, name)

	data, err := os.ReadFile(path)
	if err != nil {
		if !os.IsNotExist(err) {
			return errs.Wrap(err, errs.KindPermission, "无法备份 %s", path)
		}
		data = nil
	}
	if err := WriteFileAtomic(dst, data, 0o600); err != nil {
		return err
	}
	pruneBackups(dir)
	return nil
}

// Backup is one saved copy of a rewritten file.
type Backup struct {
	Name     string    `json:"name"`
	Path     string    `json:"path"`
	Size     int64     `json:"size"`
	Created  time.Time `json:"created"`
	Original string    `json:"original"`
}

// ListBackups returns the stored backups, newest first.
func ListBackups() ([]Backup, error) {
	dir := config.BackupDir()
	entries, err := os.ReadDir(dir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, errs.Wrap(err, errs.KindPermission, "无法读取备份目录")
	}
	var out []Backup
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".bak") {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		out = append(out, Backup{
			Name:     e.Name(),
			Path:     filepath.Join(dir, e.Name()),
			Size:     info.Size(),
			Created:  info.ModTime(),
			Original: originalFromBackupName(e.Name()),
		})
	}
	sortBackups(out)
	return out, nil
}

func originalFromBackupName(name string) string {
	// "zshenv-20060102-150405.bak" -> "zshenv"
	base := strings.TrimSuffix(name, ".bak")
	if i := strings.LastIndex(base, "-"); i > 0 {
		if _, err := time.Parse("20060102-150405", base[i+1:]); err == nil {
			return base[:i]
		}
	}
	return base
}

func sortBackups(b []Backup) {
	for i := 1; i < len(b); i++ {
		for j := i; j > 0 && b[j].Created.After(b[j-1].Created); j-- {
			b[j], b[j-1] = b[j-1], b[j]
		}
	}
}

// pruneBackups keeps only the newest config.BackupKeep backups.
func pruneBackups(dir string) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	type bak struct {
		name string
		mod  time.Time
	}
	var baks []bak
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".bak") {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		baks = append(baks, bak{e.Name(), info.ModTime()})
	}
	if len(baks) <= config.BackupKeep {
		return
	}
	sort.Slice(baks, func(i, j int) bool { return baks[i].mod.After(baks[j].mod) })
	for _, b := range baks[config.BackupKeep:] {
		_ = os.Remove(filepath.Join(dir, b.name))
	}
}

// RestoreBackup copies a backup back over the file it was taken from.
func RestoreBackup(name string) (string, error) {
	if strings.ContainsAny(name, "/\\") || name == "" {
		return "", errs.New(errs.KindInvalid, "非法的备份名")
	}
	src := filepath.Join(config.BackupDir(), name)
	data, err := os.ReadFile(src)
	if err != nil {
		return "", errs.New(errs.KindNotFound, "备份不存在: %s", name)
	}
	orig := originalFromBackupName(name)
	dst := map[string]string{
		"zshenv":       config.ZshEnv(),
		"bash_profile": config.BashProfile(),
	}[orig]
	if dst == "" {
		return "", errs.New(errs.KindInvalid, "无法确定备份对应的原文件")
	}
	if len(data) == 0 {
		// The original file did not exist.
		if err := os.Remove(dst); err != nil && !os.IsNotExist(err) {
			return "", errs.Wrap(err, errs.KindPermission, "恢复失败")
		}
		return dst, nil
	}
	if err := WriteFileAtomic(dst, data, 0o644); err != nil {
		return "", err
	}
	return dst, nil
}

// exportPattern matches a shell export assignment.
var exportPattern = regexp.MustCompile(`^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$`)

// ShellExport is one export found in a shell configuration file.
type ShellExport struct {
	Name  string `json:"name"`
	Value string `json:"value"`
	File  string `json:"file"`
	Line  int    `json:"line"`
}

// ParseShellExports extracts export assignments from a shell file.
//
// It is a best-effort reader for the read-only "Shell 配置" view; it does not
// try to evaluate the file.
func ParseShellExports(path string) []ShellExport {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var out []ShellExport
	for i, line := range strings.Split(string(data), "\n") {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		m := exportPattern.FindStringSubmatch(line)
		if m == nil {
			continue
		}
		out = append(out, ShellExport{
			Name:  m[1],
			Value: unquoteShellValue(m[2]),
			File:  path,
			Line:  i + 1,
		})
	}
	return out
}

// unquoteShellValue strips matching quotes from a raw shell value.
func unquoteShellValue(raw string) string {
	v := strings.TrimSpace(raw)
	// Strip trailing comments for unquoted values.
	if len(v) >= 2 {
		first, last := v[0], v[len(v)-1]
		if (first == '\'' && last == '\'') || (first == '"' && last == '"') {
			inner := v[1 : len(v)-1]
			if first == '\'' {
				return strings.ReplaceAll(inner, `'\''`, "'")
			}
			return inner
		}
	}
	if i := strings.Index(v, " #"); i >= 0 {
		v = strings.TrimSpace(v[:i])
	}
	return v
}
